#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Pasang SVGA Manager + Coinseller/Role (versi anti-bentrok)
# Menimpa langsung file hasil jadi (bukan diff), jadi tidak ada "patch tidak cocok".
# Jalankan di root repo:  bash pasang-svga-coinseller.sh
set -e
REPO="${REPO:-$PWD}"
cd "$REPO"
[ -d app/src/main/java/com/hayu/app ] || { echo "❌ Jalankan di root repo Hayu-android"; exit 1; }
command -v git >/dev/null 2>&1 || pkg install -y git

# Backup file lama dulu
BK=".backup-svga-coinseller"
mkdir -p "$BK"
T="$(mktemp)"
cat > "$T.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T.b64" > "$T.tgz"
tar tzf "$T.tgz" | while read -r f; do
  [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
done
tar xzf "$T.tgz"
rm -f "$T" "$T.b64" "$T.tgz"
echo "✅ File terpasang (backup lama di $BK/)"

grep -q "SvgaManagerActivity" app/src/main/AndroidManifest.xml || { echo "❌ Manifest belum terisi, hentikan"; exit 1; }

if [ -d .git ]; then
  BR=$(git rev-parse --abbrev-ref HEAD)
  grep -qx "$BK/" .gitignore 2>/dev/null || echo "$BK/" >> .gitignore
  git add -A
  git commit -m "feat: SVGA manager + coinseller stok & role BD/host" || echo "(tidak ada perubahan)"
  git pull --rebase --autostash origin "$BR" || { echo "⚠️ Ada konflik saat pull. Selesaikan, lalu: git rebase --continue && git push origin $BR"; exit 1; }
  git push origin "$BR"
  echo "✅ Terkirim ke origin/$BR"
fi
echo "Catatan: atur Firebase Storage & Firestore Rules (svgaAssets, seller_stock_requests)."
